examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    MonarchAiFeedback(
        selection = rating,
        onSelectionChange = { rating = it },
        asksDetails = MonarchAiFeedbackDetails.{{askDetails|pascal}},
    ) { submission ->
        // The app sends submission with the message id here.
        sent = submission.toString()
    }
    MonarchText(text = sent ?: "Nothing sent yet", style = MonarchTextStyle.Caption)
}

